#!/usr/bin/env bash
set -e

echo "=================================================="
echo "  DocuShift - پچ جامع رفع اتصال، ترجمه و رفرش ورودی"
echo "=================================================="

# ۱. رفتن به مسیر اصلی پروژه
if [ -d "/root/docushift" ]; then
  cd "/root/docushift"
elif [ -d "/root/Docpersian" ]; then
  cd "/root/Docpersian"
elif [ -f "server.ts" ]; then
  echo "در پوشه فعلی پروژه هستیم."
else
  echo "پوشه docushift یافت نشد! لطفاً دستور cd /root/docushift را اجرا کنید."
  exit 1
fi

echo "--> مسیر جاری: $(pwd)"

# ۲. پاکسازی کش ترجمه قدیمی
echo "--> ۱. پاکسازی کش ترجمه‌های ناقص قبلی..."
rm -rf jobs_storage/cache/*

# ۳. آزادسازی پورت ۳۰۰۰ از پروسه‌های قفل‌شده قبلی
echo "--> ۲. آزادسازی پورت ۳۰۰۰ و توقف پروسه‌های معلق..."
fuser -k 3000/tcp 2>/dev/null || true
pkill -f "tsx server.ts" 2>/dev/null || true

# ۴. استخراج کدهای اصلاح‌شده
echo "--> ۳. اعمال فایل‌های اصلاح‌شده (سرور کامپایل‌شده، فرانت و ماژول‌ها)..."
cat << 'EOF_PATCH' | base64 -d | tar -xz --overwrite

EOF_PATCH

# ۵. اطمینان از کامپایل فرانت‌اند و سرور
echo "--> ۴. کامپایل نهایی (npm run build)..."
npm run build

# ۶. تنظیم فایروال برای باز بودن پورت‌های ۸۰ و ۳۰۰۰
echo "--> ۵. بررسی و بازگشایی پورت‌های فایروال (80 و 3000)..."
if command -v ufw >/dev/null 2>&1; then
  ufw allow 80/tcp 2>/dev/null || true
  ufw allow 3000/tcp 2>/dev/null || true
fi
if command -v iptables >/dev/null 2>&1; then
  iptables -I INPUT -p tcp --dport 80 -j ACCEPT 2>/dev/null || true
  iptables -I INPUT -p tcp --dport 3000 -j ACCEPT 2>/dev/null || true
fi

# ۷. پیکربندی و راه‌اندازی مجدد Nginx (برای دسترسی آسان با پورت 80)
if command -v nginx >/dev/null 2>&1; then
  echo "--> ۶. همگام‌سازی Nginx روی پورت ۸۰..."
  mkdir -p /var/lib/nginx/body /var/cache/nginx/client_temp /tmp/nginx_upload 2>/dev/null || true
  chmod -R 777 /var/lib/nginx /tmp/nginx_upload 2>/dev/null || true
  tee /etc/nginx/sites-available/docushift >/dev/null << 'EOF_NGINX'
server {
    listen 80 default_server;
    listen [::]:80 default_server;
    server_name _;
    client_max_body_size 0;
    location / {
        proxy_pass http://127.0.0.1:3000;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_read_timeout 3600s;
        proxy_send_timeout 3600s;
        proxy_request_buffering off;
        proxy_buffering off;
    }
}
EOF_NGINX
  rm -f /etc/nginx/sites-enabled/default 2>/dev/null || true
  ln -sf /etc/nginx/sites-available/docushift /etc/nginx/sites-enabled/ 2>/dev/null || true
  nginx -t 2>/dev/null && (systemctl reload nginx 2>/dev/null || systemctl restart nginx 2>/dev/null) || true
fi

# ۸. راه‌اندازی مجدد سرویس با PM2 با استفاده از node خالص
echo "--> ۷. ثبت و اجرای DocuShift با PM2 (با موتور مستقیم node server.js)..."
pm2 delete docushift 2>/dev/null || true
pm2 delete all 2>/dev/null || true
pm2 start "node server.js" --name docushift
pm2 save 2>/dev/null || true

# ۹. تست سلامت سرویس با بررسی فعال بودن پورت
echo "--> ۸. بررسی سلامت و آمادگی سرویس..."
HEALTH_OK=0
for attempt in 1 2 3 4 5; do
  RESP=$(curl -s http://127.0.0.1:3000/api/health 2>/dev/null || echo "")
  if echo "$RESP" | grep -q '"status":"ok"'; then
    HEALTH_OK=1
    echo "پاسخ سرور: $RESP"
    break
  fi
  sleep 1
done

if [ "$HEALTH_OK" -eq 0 ]; then
  echo "⚠️ سرور نیاز به چند ثانیه بیشتر داشت. لاگ‌های جاری:"
  pm2 logs docushift --lines 10 --nostream 2>/dev/null || true
fi

SERVER_IP=$(hostname -I 2>/dev/null | awk '{print $1}')
if [ -z "$SERVER_IP" ] || [ "$SERVER_IP" = "127.0.0.1" ]; then
  SERVER_IP="141.98.210.131"
fi

echo "=================================================="
echo "  ✅ سرویس با موفقیت کامل آماده به کار شد!"
echo ""
echo "  🌐 آدرس‌های ورود به سامانه در مرورگر:"
echo "  ۱. روش اول و پیشنهادی (بدون نیاز به نوشتن پورت):"
echo "     http://${SERVER_IP}"
echo ""
echo "  ۲. روش دوم با پورت مستقیم ۳۰۰۰:"
echo "     http://${SERVER_IP}:3000"
echo "=================================================="
